import * as React from "react";

export type VolumeFaderIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function VolumeFaderIcon({ size = 20, ...props }: VolumeFaderIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="6" y="3.5" width="12" height="17" rx="2" /><path d="M9 10.5h6M9 13.5h6" />
    </svg>
  );
}
